import { useState, useCallback, useMemo } from 'react';

export function useNotificationStore() {
    const [maxCount, setMaxCount] = useState<number>(5);
    const [notifications, setNotifications] = useState<string[]>([]);
    const unreadCount = useMemo(() => { return notifications.length; }, [notifications]);
    const add = useCallback((message) => {
        if (message === "") {
            return "empty message ignored";
        }
        if (notifications.length >= maxCount) {
            return "max notifications reached";
        }
        setNotifications(prev => [...prev, message]);
        localStorage.setItem("notification-count", unreadCount.toString());
        return "added";
    }, []);
    const addWithPriority = useCallback((title, body, priority) => {
        let full = title + ": " + body;
        if (priority > 5) {
            setNotifications(prev => [...prev, full]);
            return "high priority added";
        }
        setNotifications(prev => [...prev, full]);
        return "added";
    }, []);
    const removeLast = useCallback(() => {
        if (notifications.length === 0) {
            return "no notifications";
        }
        // TODO: mutation operation 'pop' on notifications
        return "removed";
    }, []);
    const clear = useCallback(() => {
        setNotifications([]);
    }, []);
    const clearAll = useCallback(() => {
        setNotifications([]);
        localStorage.setItem("notification-count", "0");
    }, []);
    return { add, addWithPriority, removeLast, clear, clearAll, maxCount, notifications, unreadCount };
}
